res.format = function(obj) {
  var req = this.req;
  var types = Object.keys(obj);

  var best = req.accepts(types);
  if (best) {
    this.set('Content-Type', best);
    obj[best](req, this);
    return;
  }

  var notAcceptable = httpErrors(406);
  for (var type of types) {
    if (type.indexOf('*/*') !== -1 || type.indexOf('/*') !== -1) {
      this.set('Content-Type', type);
      obj[type](req, this);
      return;
    }
  }

  next(notAcceptable);
};
