res.format = function(obj) {
  var req = this.req;
  var type = req.accepts().types();
  var key = type[0] && type[0].split('/').shift();

  for (var i = 0; i < type.length; ++i) {
    var val = obj[type[i]];
    if (val) {
      this.set('Content-Type', type[i]);
      return val.call(this);
    }
  }

  if (obj.default) {
    this.set('Content-Type', 'application/octet-stream');
    return obj.default.call(this);
  }

  this.status(406).send('Not Acceptable');
};
