res.format = function(obj) {
  var req = this.req;
  var types = Object.keys(obj);

  var acceptedTypes = req.accepts(types);
  var type = acceptedTypes ? acceptedTypes[0] : false;

  if (!type) {
    this.statusCode = 406;
    return this.end();
  }

  var body = obj[type];
  if (typeof body === 'function') {
    body = body.call(this);
  }

  this.set('Content-Type', type);
  this.end(body);
};
