res.format = function(obj) {
  var req = this.req;
  var vary = this.vary;

  // get accepted types
  var acceptedTypes = req.accepts();
  var type = acceptedTypes[0];

  // set vary
  vary('Accept');

  // respond
  for (var key in obj) {
    if (key === type) {
      return obj[key].call(this);
    }
  }

  // default to json
  if (obj.default) {
    return obj.default.call(this);
  }

  // if no type matches, respond with 406 Not Acceptable
  this.statusCode = 406;
  this.end();
};
